const characterVisuals={Guerrero:{Guardia:{sigil:'✦',accent:'#d9b56c',tint:0xf3d39a},Berserker:{sigil:'✹',accent:'#e47f5f',tint:0xf1ae8d}},Pícaro:{Sombra:{sigil:'◈',accent:'#8fc8b1',tint:0xbfe2d0},Explorador:{sigil:'✧',accent:'#c7d98c',tint:0xd7e6ae}},Mago:{Arcanista:{sigil:'✧',accent:'#b9aaf4',tint:0xd0c8ff},Tejedor:{sigil:'◌',accent:'#d6a17c',tint:0xe3b59a}}};
const genderVisuals={Mujer:{className:'woman',sigil:'✧'},Hombre:{className:'man',sigil:'◆'},'No binario':{className:'nonbinary',sigil:'◇'}};
const raceVisuals={Humano:{sigil:'◇'},Elfo:{sigil:'✧'},Enano:{sigil:'⬟'},Orco:{sigil:'◆'},Mediano:{sigil:'•'},Gnomo:{sigil:'✿'},Semielfo:{sigil:'◈'},Semiorco:{sigil:'✹'}};
function characterVisual(){const cls=characterVisuals[character?.class]||characterVisuals.Guerrero,sub=cls[character?.subclass]||Object.values(cls)[0],gender=genderVisuals[character?.gender]||genderVisuals['No binario'],race=raceVisuals[character?.race]||raceVisuals.Humano;return{className:character?.class||'Guerrero',subclass:character?.subclass||Object.keys(cls)[0],gender:character?.gender||'No binario',race:character?.race||'Humano',sigil:sub.sigil,accent:sub.accent,tint:sub.tint,genderClass:gender.className,genderSigil:gender.sigil,raceSigil:race.sigil};}
function characterReady(candidate=character){return typeof candidate?.name==='string'&&candidate.name.trim().length>0&&CD.raceData[candidate.race]&&CD.classes[candidate.class]&&CD.subclassData[candidate.class]?.some(entry=>entry[0]===candidate.subclass)&&CD.genderData.some(entry=>entry[0]===candidate.gender)&&Array.isArray(candidate.base)&&candidate.base.length===6;}
function ensureCreatorStyles(){if(document.getElementById('creator-style'))return;const style=document.createElement('style');style.id='creator-style';style.textContent='#character-onboarding{width:min(1080px,calc(100% - 24px));height:min(860px,calc(100dvh - 24px));max-width:none;padding:22px;background:linear-gradient(145deg,#f4ead2,#e5d2a6);color:#243d31;border:1px solid #c39b55;border-radius:18px;box-shadow:0 24px 90px #061710cc;overflow:hidden}#character-onboarding::backdrop{background:#061710d9;backdrop-filter:blur(7px)}#character-onboarding h2{margin:3px 0 2px;font-size:30px}#character-onboarding .creator-kicker{font:11px system-ui;letter-spacing:.18em;color:#8c6a30}#character-onboarding .creator-intro{margin:5px 0 12px;max-width:760px;font:14px/1.5 system-ui;color:#5b604d}#character-onboarding iframe{display:block;width:100%;height:calc(100% - 130px);border:1px solid #c8b27d;border-radius:12px;background:#151916}#character-onboarding .creator-actions{display:flex;justify-content:space-between;align-items:center;gap:14px;padding-top:12px;font:12px system-ui;color:#5b604d}#character-onboarding .creator-actions button{min-height:46px;padding:10px 18px;background:linear-gradient(180deg,#f3d37f,#c18a42);border-color:#ffe5a0;color:#1c3029;box-shadow:0 7px 16px #604c2a44}body[data-hero-class="Mago"] #battle [data-unit="hero"] .combat-art{filter:hue-rotate(36deg) saturate(1.14) brightness(1.05)}body[data-hero-class="Pícaro"] #battle [data-unit="hero"] .combat-art{filter:hue-rotate(118deg) saturate(.86) brightness(.94)}body[data-hero-class="Guerrero"] #battle [data-unit="hero"] .combat-art{filter:saturate(1.08) brightness(1.04)}body[data-hero-subclass="Berserker"] #battle [data-unit="hero"] .combat-art{filter:hue-rotate(-12deg) saturate(1.3) brightness(1.03)}body[data-hero-subclass="Arcanista"] #battle [data-unit="hero"] .combat-art{filter:hue-rotate(24deg) saturate(1.22) brightness(1.08)}body[data-hero-subclass="Tejedor"] #battle [data-unit="hero"] .combat-art{filter:hue-rotate(-16deg) saturate(1.15)}@media(max-width:650px){#character-onboarding{height:calc(100dvh - 12px);width:calc(100% - 12px);padding:14px;border-radius:14px}#character-onboarding h2{font-size:24px}#character-onboarding .creator-intro{font-size:12px;margin-bottom:8px}#character-onboarding iframe{height:calc(100% - 142px)}#character-onboarding .creator-actions{align-items:stretch;flex-direction:column;gap:7px}#character-onboarding .creator-actions button{width:100%}}';document.head.append(style)}
function applyHeroVisual(target=scene){const v=characterVisual();document.body.dataset.heroClass=v.className;document.body.dataset.heroSubclass=v.subclass;document.body.dataset.heroGender=v.gender;document.body.dataset.heroRace=v.race;if(!target?.hero)return;target.hero.setTint(v.tint);target.heroAura??=target.add.ellipse(target.hero.x,target.hero.y,58,19,0x1b322a,.22).setDepth(target.hero.y-.2);target.heroBadge??=target.add.text(target.hero.x,target.hero.y-104,v.sigil,{fontFamily:'Georgia',fontSize:'22px',color:v.accent,stroke:'#16271f',strokeThickness:4}).setOrigin(.5,1).setDepth(2200);target.heroAura.setFillStyle(v.tint,.22).setPosition(target.hero.x,target.hero.y+2).setDepth(target.hero.y-.2);target.heroBadge.setText(v.sigil+' '+v.raceSigil+' '+v.genderSigil).setColor(v.accent).setPosition(target.hero.x,target.hero.y-104).setDepth(target.hero.y-1);}
function openCharacterCreator(){if($('character-onboarding'))return;const dialog=document.createElement('dialog');dialog.id='character-onboarding';dialog.innerHTML='<div class="creator-kicker">CENIZAS DEL UMBRAL · PRÓLOGO</div><h2>Antes de cruzar el puente</h2><p class="creator-intro">Tu historia empieza con una decisión. Elige clase, subclase y género para que tu silueta, emblema y presencia en Valdara sean tuyos.</p><iframe title="Creación de personaje" src="character.html?campaign=1&creator=1"></iframe><div class="creator-actions"><span id="creator-status">Guarda tu personaje en la hoja y vuelve aquí para comenzar.</span><button id="creator-enter" type="button">Entrar a Valdara</button></div>';document.body.append(dialog);const status=dialog.querySelector('#creator-status'),enter=dialog.querySelector('#creator-enter');enter.onclick=()=>{let c=null;try{c=JSON.parse(localStorage.getItem('cenizas-character-v1'));}catch{}if(!c||!characterReady(c)){status.textContent='Completa nombre, clase, subclase y género antes de entrar.';return;}character=c;heroProfile=window.CenizasEquipment.profile(R,character,state);dialog.close();dialog.remove();applyHeroVisual();hud();save();};dialog.addEventListener('cancel',e=>e.preventDefault());dialog.addEventListener('close',()=>{if(document.body.contains(dialog))dialog.remove();});dialog.showModal();}
