const waySigns={montana:{at:[505,845],text:'↙ Monasterio.\n↗ Sigue el sendero de piedra hasta la entrada en la montaña.'},antesala:{at:[920,810],text:'↓ Sendero de la montaña.\n↑ Puerta del Umbral.'},umbral:{at:[925,810],text:'↓ Antesala.\n↑ Piedra ancla y conductores.'},capilla:{at:[950,780],text:'↓ Patio del monasterio.\n↑ Capilla y campanas del sello.'},enfermeria:{at:[1120,710],text:'← Camas y zona de atención.\n↗ Plataforma de la campana.\n↘ Umbral abierto hacia el patio.'},monasterio:{at:[1000,690],text:'↖ Enfermería: arco del claustro izquierdo.\n↑ Sereth recibe a los viajeros en el patio.\n← Novicio: pregunta por Darien.\n↗ Archivo: puerta grande del fondo.\n→ Capilla: puerta iluminada con vitral y campana, al extremo derecho.\n↓ Regreso al mirador y al bosque.'},archivo:{at:[1220,780],text:'Archivo de la Vigilia.\nConserva el orden de los libros.\n→ Salida al patio.'},molino:{at:[320,835],text:'↙ Embarcadero y Tovin.\n↗ Molino y carga: sigue el sendero de la garganta. Hay ecos en el camino.'},embarcadero:{at:[1040,530],text:'↗ Bosque de los Susurros: sube por el camino.\n← Tovin y el embarcadero.\n↓ Descanso. Más abajo: sendero a la garganta del molino.'},lindero:{at:[780,590],text:'↙ Valdara: sigue el camino de regreso.\n↗ Claro de Iria: atraviesa el lindero. Los fragmentos de campana pueden atraer ecos.\n↖ Cofre: entra al claro por el desvío de la derecha y bordea las raíces.'},plaza:{at:[920,755],text:'↙ Taller de Ordan: puerta bajo el toldo azul, en la parte baja izquierda.\n↖ Bosque: sigue el sendero de piedra hacia el arco entre los árboles, arriba a la izquierda.\n← Puente de Valdara: acceso de regreso.'},taller:{at:[855,620],text:'← Ordan y zona de descanso.\n↙ Escalera a las criptas, junto al fondo del taller.\n→ Salida a la plaza.'},criptas:{at:[930,690],text:'← Puesto de la Vigilia.\n↖ Registro y compuerta.\n→ Escalera de regreso al taller.'},bosque:{at:[720,618],text:'↙ Abajo: regreso al Lindero de Valdara y, después, a la plaza.\n↖ Voz entre raíces y carro abandonado: sube por la senda de piedra.\n↗ Arriba a la derecha: camino al monasterio, pasando el puente y Bren. Acércate al mirador y elige «Continuar al monasterio».\n↖ Arriba a la izquierda: raíces, carro y huellas; esa senda no lleva al monasterio.\n↘ Abajo a la derecha, después del puente: embarcadero de la Vigilia.'}};
