function archiveDiscussion(){
 if(state.flags.archiveCompared){say('Elara','Tenemos motivos para exigir que abran el ala oeste. Darien está en la enfermería. El novicio puede ayudarnos.',[['Volver a explorar',()=>{}],['Ver el mapa',map]]);return;}
 const choices=[];
 if(Investigation.ready(state)&&!state.flags.archiveReviewRequired)choices.push(['Exponer una conclusión',archiveHypothesis]);
 choices.push(['Repasar lo que encontramos',journal],['Pedir una pista a Elara',()=>say('Elara',Investigation.hint(state),[['Seguir investigando',()=>{}]])],['Seguir investigando',()=>{}]);
 say('Elara',state.flags.archiveReviewRequired?'Antes de insistir, volvamos a mirar los documentos. No quiero acusar a alguien con una explicación que no se sostiene.':'Sereth habla de protección. ¿Lo que hemos visto respalda su historia?',choices);
}
function archiveHypothesis(){
 say('Tu interpretación','¿Qué crees que está haciendo la Vigilia?',[
 ['Mantiene el juramento de los antiguos custodios',()=>archiveSupport('continuity')],
 ['Sustituye a los custodios sin consentimiento',()=>archiveSupport('substitution')],
 ['Solo está corrigiendo errores de sus registros',()=>archiveSupport('clerical')],
 ['Todavía no quiero concluir',()=>{}]
 ]);
}
function archiveSupport(claim){
 say('Sostener la conclusión','¿Qué relación entre tus notas permite afirmarlo?',[
 ['Ordan firmó el acta; por tanto, autorizó los traslados actuales',()=>archiveResolve(claim,'ordan')],
 ['Las raciones prueban que los residentes aceptaron quedarse',()=>archiveResolve(claim,'rations')],
 ['El acta exige voluntad; el traslado y la transcripción no la acreditan',()=>archiveResolve(claim,'consent')],
 ['Volver a mis notas',journal]
 ]);
}
function archiveResolve(claim,support){
 const result=Investigation.deduce(state,claim,support);save();hud();
 if(result==='solved'){note('Relacionaste el acta, los traslados y las transcripciones: la Orden usa nombres sin consentimiento. El novicio abrirá el ala oeste al conocer tus hallazgos.');say('Elara','Una copia puede repetir un nombre, pero no la voluntad de quien lo lleva. Llevemos esto al ala oeste: ahora sabemos qué preguntar.',[['Buscar el ala oeste en el patio',()=>{}],['Ver el mapa',map]]);return;}
 if(result==='complete'){archiveDiscussion();return;}
 say('Elara',result==='contradiction'?'Esa explicación da por probado algo que esos papeles no dicen. Revisemos la fuente antes de presentársela al novicio.':'Todavía necesitamos contrastar nuestras notas.',[['Volver a investigar',()=>{}],['Consultar mis notas',journal]]);
}
function darienTalk(){
 if(state.flags.captivesFreed){if(!state.flags.darienDebrief){state.flags.darienDebrief=true;note('Darien confirmó que todos los cautivos están a salvo.');hud();}say('Darien','Los cautivos ya están fuera del alcance de la campana. Elara, no cierres la puerta detrás de nosotros. La capilla de Sereth será el próximo paso.',[['Volver al patio',()=>travel('monasterio')],['Revisar el diario',journal]]);return;}
 if(!state.flags.darienMet){state.flags.darienMet=true;note('Encontraste a Darien. La campana mantiene vinculados a los cautivos; hay que desconectarla antes de sacarlos.');}hud();
 say('Darien','Tardaste. Ya estaba pensando en escribir una queja a la guardia.',[['Elara: puedes presentarla cuando salgas',()=>say('Darien','La campana nos mantiene atados al registro. Si intentamos salir ahora, caeremos antes de llegar al patio. Un eco protege el conducto de la derecha. Aíslen su foco y podremos desconectar el mecanismo.',[['Buscar la campana',()=>{}],['Prepararme antes de actuar',inventory]])],['Preguntar cómo resisten los cautivos',()=>say('Darien','Cuento los golpes de las tuberías para avisarles de las patrullas. Mientras ustedes silencian la campana, mantendré al grupo unido.')]]);
}
async function infirmaryBell(){
 if(state.flags.captivesFreed){say('Campana en silencio','El mecanismo está desconectado. Habla con Darien para comprobar que todos están a salvo.');return;}
 if(!state.flags.darienMet){say('La campana inferior','Las tuberías vibran al ritmo de la respiración de los cautivos. Darien conoce este mecanismo: habla con él antes de tocarlo.');return;}
 if(!state.flags.infirmaryEcho){revealEncounter({id:'enfermeria-campana',flag:'infirmaryEcho',x:1150,y:440,title:'La voz junto a la campana',text:'La ceniza intenta repetir la voz de Darien. Él responde desde las camas: «Yo estoy aquí». Elara se coloca junto a ti. Aísla el foco o derrota al Eco del murmullo para alcanzar el conducto.'});return;}
 if(!state.flags.ordanArrived){await runStage([{text:'Unos pasos llegan desde el patio. Ordan trae el plano del conducto.',focus:[1100,610],moves:[['ordanRescue',[[1400,865],[1100,660],[980,450],[1160,410]]]]}]);state.flags.ordanArrived=true;save();}
 say('Ordan · la carta y la campana','Ordan extiende su plano junto al conducto. Darien reconoce la letra de la carta. «Te escribí porque necesitaba que alguien viniera —confiesa Ordan—. No te dije todo porque temí que nadie lo hiciera».', [['Me usaste',()=>disconnectInfirmary('reproche')],['Debiste confiar en mí',()=>disconnectInfirmary('confianza')],['Ahora termina lo que empezaste',()=>disconnectInfirmary('colaboracion')],['Prepararme antes de desconectar',()=>{}]]);
}
async function disconnectInfirmary(response){
 if(state.flags.captivesFreed||!state.flags.infirmaryEcho||!state.flags.darienMet||encounterBusy)return;
 state.flags.ordanResponse=response;
 await runStage([
 {text:'Ordan afloja la abrazadera del conducto. Elara sostiene el mecanismo mientras retiras el registro.',focus:[1200,330],moves:[['ordanRescue',[[1160,410],[1230,395]]],['ally',[[1050,520],[1160,455]]],['hero',[[1100,505],[1210,460]]]]},
 {text:'La última vibración se extingue. Los cautivos levantan la cabeza: la campana ya no tira de sus nombres.',focus:[750,400],quietBell:true},
 {text:'Darien: «De uno en uno. Liora, acompaña a Ada; Tomás, no dejes a nadie atrás».',focus:[1000,620],moves:[['darien',[[750,490],[1060,650],[1400,865]]],['patientA',[[670,450],[980,620],[1370,865]]],['patientB',[[880,440],[1020,620],[1340,850]]],['patientC',[[1010,440],[1080,650],[1310,830]]],['attendant',[[810,480],[1010,650],[1290,845]]]]}
 ]);
 state.flags.captivesFreed=true;state.flags.rescueSeen=true;
 state.level=Math.max(4,state.level);const oldMax=heroProfile.max;heroProfile=window.CenizasEquipment.profile(R,character,state);state.hp=Math.min(heroProfile.max,state.hp+heroProfile.max-oldMax);
 item('Plano de la campana inferior');note('Nadie queda atrás: Darien y el personal evacuaron a los cautivos por el umbral del patio. Nivel 4.');scene.enter();hud();
 say('Elara','Los he visto salir. Están a salvo. Ahora Sereth tendrá que escucharnos.',[['Salir al patio',()=>travel('monasterio')],['Quedarme un momento',()=>{}]]);
}
function stagedCast(){
 let list=(residents[state.place]||[]).map(x=>x.slice());if(state.place==='umbral'&&state.flags.umbralClosed){if(!state.flags.serethSaved)list=list.filter(x=>x[0]!=='serethFinal');else list=list.map(x=>x[0]==='serethFinal'?['serethFinal',0,920,670]:x);}if(state.place==='plaza'&&state.flags.campaignComplete)list.push(['darien','darien',850,800],['ordanChapel',1,700,840]);
 if(state.place==='enfermeria'){
  if(state.flags.captivesFreed)list=list.filter(x=>!['darien','patientA','patientB','patientC'].includes(x[0]));
  if(state.flags.ordanArrived&&!state.flags.captivesFreed)list.push(['ordanRescue','darien',1160,410]);
 }
  if(state.place==='monasterio'&&state.flags.iriaJoined&&!state.flags.captivesFreed)list.push(['ranger',3,1040,610]);
  if(state.place==='monasterio'&&state.flags.captivesFreed){list=list.filter(x=>x[0]!=='sereth');list.push(['darien','darien',720,480],['patientA','darien',570,565],['patientB','darien',640,560],['patientC','darien',710,570],['attendant','darien',590,620]);if(state.flags.iriaJoined)list.push(['ranger',3,820,610]);}
  if(state.place==='capilla'&&state.flags.captivesFreed){list.push(['nurse',0,520,620]);if(state.flags.iriaJoined)list.push(['ranger',3,1000,640]);}
  if(state.place==='capilla'&&state.flags.chapelWon)list=list.filter(x=>!['mara','serethChapel'].includes(x[0]));
 return list;
}
async function runStage(steps){
 if(encounterBusy||battle)return;
 if($('story').open)close('story');
 stop();encounterBusy=true;const cam=scene.cameras.main;cam.stopFollow();
 const box=document.createElement('section');box.className='story-stage';box.setAttribute('aria-live','polite');const text=document.createElement('p'),next=document.createElement('button');next.textContent='Continuar';box.append(text,next);document.body.append(box);
 const walk=async(id,path)=>{let actor=id==='hero'?scene.hero:id==='ally'?scene.ally:scene.npcs.find(n=>n.npcId===id);if(!actor){console.warn('Escena omitida: no existe el NPC '+id);return;}
 for(const [x,y]of path){const sx=actor.x,sy=actor.y,d=Math.hypot(x-sx,y-sy);await new Promise(done=>scene.tweens.add({targets:actor,x,y,duration:Math.max(250,d/115*1000),ease:'Linear',onUpdate:()=>{actor.setDepth(actor.y);if(actor===scene.hero||actor===scene.ally)Motion.frame(actor,(x-sx)/Math.max(d,1)*2,(y-sy)/Math.max(d,1)*2,16);else NPCs.step(actor,(x-sx)/Math.max(d,1)*2,(y-sy)/Math.max(d,1)*2,16);},onComplete:done}));}if(actor===scene.hero||actor===scene.ally)Motion.frame(actor,0,0,16);else NPCs.step(actor,0,0,16);};
 try{for(const step of steps){text.textContent=step.text;next.disabled=true;if(step.focus)cam.pan(...step.focus,900,'Sine.easeInOut');if(step.quietBell)scene.bellQuiet=true;await Promise.all((step.moves||[]).map(([id,path])=>walk(id,path)));await new Promise(done=>scene.time.delayedCall(1200,done));next.disabled=false;next.focus({preventScroll:true});await new Promise(done=>next.onclick=()=>{next.disabled=true;next.onclick=null;done();});}}
 finally{box.remove();encounterBusy=false;cam.startFollow(scene.hero,true,.12,.12);scene.follower=new Motion.Follower(scene.hero.x,scene.hero.y);state.position={x:scene.hero.x,y:scene.hero.y};stop();}
}
function chapelTalk(){
 if(state.flags.chapelWon){chapelAfter();return;}
 if(state.flags.chapelRevealed){say('Ordan','Los soportes alimentan al Guardián. Podemos apagarlos y accionar la palanca central. No hace falta sacrificar a nadie.',[['Enfrentar al Guardián de ceniza',()=>startBattle('ash')],['Prepararme',inventory],['Volver al patio',()=>travel('monasterio')]]);return;}
 say('Sereth','No vuelvas a decir que ella no está aquí. Mara recuerda mi nombre. Recuerda nuestra casa.',[
 ['Darien: preguntarle por el presente',()=>say('Darien','Si eres Mara, ¿qué está ocurriendo fuera de esta habitación?', [['Escuchar su respuesta',chapelReveal]])],
 ['Mostrar las firmas del archivo',()=>say('Sereth','Hice lo necesario para sostener el sello. Nadie más estaba dispuesto.', [['Elara: sin pedirles permiso',chapelReveal]])],['Observar antes de hablar',()=>{}]]);
}
async function chapelReveal(){
 await runStage([{text:'La figura repite un nombre antiguo. Sus labios se mueven; otras voces responden desde las dos campanas.',focus:[770,260]}, {text:'Ordan hace resonar el diapasón. La silueta pierde su contorno: son recuerdos superpuestos, no una persona que haya vuelto.',focus:[770,350]}]);
 scene.npcs.find(n=>n.npcId==='mara')?.setAlpha(.18);
 state.flags.chapelRevealed=true;note('Mara no pudo responder sobre el presente. El diapasón reveló voces prestadas. Sereth activó los soportes de la capilla.');hud();
 say('Sereth','Todavía puedo completar el llamado. No dejaré que me la quiten otra vez.',[['Ver qué despierta',()=>revealEncounter({kind:'ash',id:'guardian-ceniza',flag:'chapelWon',x:800,y:440,title:'Guardián de ceniza',text:'Dos campanas laten fuera de ritmo. Entre ambas, la ceniza aprende a sostener un martillo.',detail:'J02 · 42 PG, CA 16. Dos soportes alimentan sus ataques. Ordan señala la palanca central.'})]]);
}
