 await runStage([{text:'Darien se queda con los rescatados. Ordan toma la delantera; Elara comprueba que lo sigues antes de cruzar la puerta.',focus:[770,800],moves:[['ordanChapel',[[600,650],[720,740],[740,850]]],['hero',[[770,700],[800,850]]],['ally',[[700,700],[760,850]]]]}]);
