async function bellMemory(){
 if(encounterBusy||battle)return false;stop();encounterBusy=true;
 try{const seen=await window.CenizasBellCinema.show();if(seen&&!state.flags.bellCinemaSeen){state.flags.bellCinemaSeen=true;note('Ordan reconstruyó el accidente: una campana del Umbral cayó de un carro de la Vigilia al romperse el eje. El fragmento conservó el vínculo con el Coro.');}return seen;}
 finally{encounterBusy=false;stop();save();}
}
async function mountainVoice(){
 if(!state.flags.bellCinemaSeen){if(!await bellMemory())return;}

 if(state.flags.mountainEcho){say('Elara','La voz se ha apagado. La entrada del Umbral está al final del sendero.',[['Recordar cómo cayó la campana',bellMemory],['Seguir por el sendero',()=>{}]]);return;}
 if(!state.flags.mountainReason){say('Una voz en la piedra','«Puedes marcharte. Nadie te reclamará nada». Elara mira el fragmento: «No le debes tu vida a Ordan. Si seguimos, que sea por una razón nuestra».',[
 ['Por la gente de Valdara',()=>chooseReason('valdara')],['Por quienes caminan conmigo',()=>chooseReason('companeros')],['Para que se conozca la verdad',()=>chooseReason('verdad')],['Para que nadie decida por nosotros',()=>chooseReason('libertad')],['Recordar cómo cayó la campana',bellMemory],['Alejarme del fragmento',()=>{}]]);return;}
 revealEncounter({id:'mountain-fragment',flag:'mountainEcho',x:690,y:535,title:'El último murmullo',text:'El fragmento repite tu respuesta, pero no entiende por qué la elegiste. Un Eco del murmullo se forma sobre el sendero. Ordan señala el foco que lo sostiene.'});
}
function chooseReason(reason){if(!state.flags.mountainReason){state.flags.mountainReason=reason;note('Decidiste continuar por '+({valdara:'Valdara',companeros:'tus compañeros',verdad:'la verdad',libertad:'la libertad'}[reason])+'.');}mountainVoice();}
