 animateResidents(dt){for(const n of this.npcs){if(n.route){const target=n.route[n.waypoint],dx=target[0]-n.x,dy=target[1]-n.y,d=Math.hypot(dx,dy);n.pause-=dt;if(n.pause>0||Math.hypot(n.x-this.hero.x,n.y-this.hero.y)<85){NPCs.step(n,0,0,dt);continue;}if(d<3){n.waypoint=(n.waypoint+1)%n.route.length;n.pause=1800;NPCs.step(n,0,0,dt);continue;}const step=Math.min(d,35*Math.min(dt,40)/1000),x=n.x+dx/d*step,y=n.y+dy/d*step;if(Nav.clear(rooms[state.place],n,{x,y})){n.setPosition(x,y).setDepth(y);NPCs.step(n,dx/d*step,dy/d*step,dt);}}else{n.idleTime=(n.idleTime||0)+dt;n.setScale(n.baseScaleX,n.baseScaleY*(1+Math.sin(n.idleTime/550)*.015));n.setAngle(n.npcId==='ordan'?Math.sin(n.idleTime/320)*2:Math.sin(n.idleTime/950)*.7);}const label=this.labels.find(t=>t.npcId===n.npcId);if(label)label.setPosition(n.x,n.y-103);}}
